<template>
  <!-- Visually hidden h1 for accessibility (WCAG page-has-heading-one) -->
  <h1 class="sr-only">{{ $t('settings') }}</h1>
  <SubHeader
    name="settings"
    :label="$t('settings')"
    :onSearch="false"
  />

  <div class="settings-layout" data-test="settings-layout">
    <!-- Loading State -->
    <div v-if="isLoadingProfile" class="loading-container q-pa-xl text-center">
      <q-spinner-dots color="primary" size="50px" />
      <p class="q-mt-md text-grey-6">{{ $t('loading') || 'Loading...' }}</p>
    </div>

    <!-- Profile Load Error -->
    <div v-else-if="isProfileError" class="loading-container q-pa-xl text-center">
      <q-icon name="wifi_off" size="80px" color="grey-6" />
      <h4 class="q-mt-md q-mb-sm text-grey-8">
        {{ $t('connection_error') || 'Connection Error' }}
      </h4>
      <p class="text-grey-6 q-mb-lg">
        {{ $t('profile_load_failed') || 'Could not load your profile. Please try again.' }}
      </p>
      <q-btn
        color="primary"
        :label="$t('retry') || 'Retry'"
        @click="retryProfile"
        no-caps
      />
    </div>

    <!-- Admin Only Access Message -->
    <div v-else-if="!isAdmin && !isSupplier" class="access-denied-container" data-test="settings-access-denied">
      <q-card class="access-denied-card text-center q-pa-xl">
        <q-icon name="admin_panel_settings" size="80px" color="grey-6" />
        <h4 class="q-mt-md q-mb-sm text-grey-8">
          {{ $t('admin_only_title') || 'Admin Access Required' }}
        </h4>
        <p class="text-grey-6 q-mb-lg">
          {{ $t('admin_only_message') || 'Settings are only available for organization administrators. Please contact your administrator for access.' }}
        </p>
        <q-btn
          color="primary"
          :label="$t('back_to_dashboard') || 'Back to Dashboard'"
          @click="$router.push('/dashboard')"
          no-caps
        />
      </q-card>
    </div>

    <!--
      Main Settings Layout
      NOTE: Uses v-show instead of v-else to avoid a Vue 3 fragment patching bug.
      q-drawer uses Teleport internally, which breaks DOM insertion when switching
      v-if/v-else branches with 4+ conditions. v-show keeps the element in the DOM
      and avoids the detached-node issue entirely.
    -->
    <div
      v-show="!isLoadingProfile && !isProfileError && isAdmin"
      class="settings-layout-body"
      :class="{ 'settings-layout-body--collapsed': sidebarCollapsed }"
    >
      <!-- Mobile sidebar toggle -->
      <q-btn
        v-if="isMobileView"
        flat
        round
        dense
        icon="menu"
        class="sidebar-toggle"
        @click="sidebarOpen = true"
      />

      <!-- Mobile: sidebar as drawer -->
      <q-drawer
        v-if="isMobileView"
        v-model="sidebarOpen"
        bordered
        side="left"
        :width="280"
        :breakpoint="0"
        overlay
        behavior="mobile"
      >
        <SettingsSidebar
          :categories="categories"
          :active-route="$route.path"
          @item-click="sidebarOpen = false"
        />
      </q-drawer>

      <!-- Desktop: sidebar always visible -->
      <div v-if="!isMobileView" class="settings-sidebar-wrapper">
        <SettingsSidebar
          :categories="categories"
          :active-route="$route.path"
          :collapsed="sidebarCollapsed"
          @update:collapsed="sidebarCollapsed = $event"
        />
      </div>

      <!-- Content area -->
      <div class="settings-content-area">
        <router-view />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import SettingsSidebar from 'src/pages/Settings/Components/SettingsSidebar.vue';
import { useSettingsNavigationStore } from 'src/store/settings-navigation';
import { useUserStore, useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { isUserAdmin, isSupplierUser, getSupplierDetailsRoute } from 'src/utils/UserDetails';
import { supplier_dashboard_setting } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import type { CategoryData } from 'src/@types/settings';

export default defineComponent({
  name: 'SettingsLayout',

  components: {
    SubHeader,
    SettingsSidebar,
  },

  setup() {
    const navStore = useSettingsNavigationStore();
    const userStore = useUserStore();
    const settingStore = useSettingStore();
    const { user_settings } = storeToRefs(settingStore);

    return {
      navStore,
      userStore,
      user_settings,
      supplier_dashboard_setting,
    };
  },

  data() {
    return {
      isLoadingProfile: true,
      isAdmin: false,
      isSupplier: false,
      isProfileError: false,
      sidebarOpen: false,
      sidebarCollapsed: false,
      windowWidth: window.innerWidth,
      resizeTimer: null as ReturnType<typeof setTimeout> | null,
    };
  },

  computed: {
    isMobileView(): boolean {
      return this.windowWidth < 768;
    },

    categories(): CategoryData[] {
      return this.navStore.getCategories(this.$t, {
        isAdmin: this.isAdmin,
        isSupplier: this.isSupplier,
        supplierDashboardEnabled:
          toBoolPreference(this.user_settings[this.supplier_dashboard_setting]),
        supplierDetailsRoute: getSupplierDetailsRoute(),
      });
    },
  },

  async mounted() {
    window.addEventListener('resize', this.handleResize);

    try {
      await this.userStore.getProfile();
      this.isAdmin = isUserAdmin();
      this.isSupplier = isSupplierUser();
    } catch {
      this.isProfileError = true;
    } finally {
      this.isLoadingProfile = false;
    }
  },

  beforeUnmount() {
    window.removeEventListener('resize', this.handleResize);
    if (this.resizeTimer) clearTimeout(this.resizeTimer);
  },

  methods: {
    handleResize() {
      if (this.resizeTimer) clearTimeout(this.resizeTimer);
      this.resizeTimer = setTimeout(() => {
        this.windowWidth = window.innerWidth;
      }, 150);
    },

    async retryProfile() {
      this.isProfileError = false;
      this.isLoadingProfile = true;
      try {
        await this.userStore.getProfile();
        this.isAdmin = isUserAdmin();
      } catch {
        this.isProfileError = true;
      } finally {
        this.isLoadingProfile = false;
      }
    },
  },
});
</script>

